import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long A = 0, B = 1; // Initialize with some default
        long minA = 0, minB = 1; // Initialize with some default
        for (long i = 1; i <= n; ++i) {
            long k = x * i / y;
            if (i == 1) {
                A = k;
                B = i;
            }
            for (int j = 0; j <= 10; ++j) {
                long candidate_k = k + j;
                long mn1 = Math.abs(x * i - y * candidate_k) * y * (long) B;
                long mn2 = Math.abs(x * (long) B - y * (long) A) * y * i;
                if (i == 1 && j == 0) {
                    minA = A;
                    minB = B;
                }
                if (mn1 < mn2) {
                    A = candidate_k;
                    B = i;
                }
            }
        }
        long g = gcd(A, B);
        System.out.println((A / g) + "/" + (B / g));
        sc.close();
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
